"""Generate the shared public shell and initial content; no runtime CSS compiler."""
from pathlib import Path
import json,html
WEB=Path(__file__).resolve().parents[1]/'main website file'
D=json.loads((WEB/'assets/website-defaults.json').read_text())
e=lambda x:html.escape(str(x),quote=True)
nav=[('Home','/'),('Services','/services'),('Portfolio','/portfolio'),('About','/about'),('Work with ICSS','/work-with-icss')]
def brand():return '<a class="brand" href="/" aria-label="iCreate Solutions and Services home"><img src="/assets/icss-logo.png" width="43" height="43" alt=""><span><strong>iCreate</strong><small>Solutions &amp; Services</small></span></a>'
def shell(name,title,desc,body):
 links=''.join(f'<a href="{url}"'+(' aria-current="page"' if title==label or (name=='index' and label=='Home') else '')+f'>{label}</a>' for label,url in nav)
 foot=lambda items:'<ul>'+''.join(f'<li><a href="{url}">{label}</a></li>' for label,url in items)+'</ul>'
 url='/' if name=='index' else '/'+name
 return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | iCreate Solutions &amp; Services</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="https://icreatesolutionsandservices.com{url}"><meta property="og:type" content="website"><meta property="og:title" content="{e(title)} | iCreate Solutions &amp; Services"><meta property="og:description" content="{e(desc)}"><meta property="og:image" content="https://icreatesolutionsandservices.com/assets/icss-logo.png"><meta property="og:url" content="https://icreatesolutionsandservices.com{url}"><meta name="theme-color" content="#081a36"><link rel="icon" href="/assets/icss-logo.png"><link rel="stylesheet" href="/assets/css/site.css?v=20261029"><script defer src="/assets/js/site.js?v=20261029"></script></head>
<body data-page="{name}"><a class="sr-only" href="#main">Skip to content</a><header class="site-header"><div class="wrap header-row">{brand()}<button class="menu-toggle" type="button" aria-label="Toggle navigation" aria-expanded="false" aria-controls="site-nav">Menu</button><nav id="site-nav" class="site-nav" aria-label="Main navigation">{links}<a class="nav-cta" href="/contact">Let's talk ↗</a></nav></div></header><main id="main">{body}</main>
<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div>{brand()}<p>Transforming Ideas into Powerful Digital Experiences.</p><p>Built in Jamaica.<br>Made for businesses everywhere.</p></div><div><h3>Explore</h3>{foot(nav[1:]+[('Contact','/contact')])}</div><div><h3>Build with us</h3>{foot([('Web development','/web-development.html'),('Mobile applications','/mobile-app-development.html'),('Business automation','/business-automation.html'),('Subscriptions & support','/subscriptions.html'),('Project planner','/project-planner.html#project-estimator')])}</div><div><h3>Connect</h3>{foot([('LinkedIn','https://www.linkedin.com/company/icreate-solutions-services/'),('Instagram','https://www.instagram.com/icreate_solutions/'),('WhatsApp','https://wa.me/18765857469'),('Email','mailto:iCreatesolutions.ja@gmail.com')])}</div></div><div class="footer-bottom"><span>© {2026} iCreate Solutions &amp; Services. All rights reserved.</span><span><a href="/terms.html">Terms &amp; privacy</a> &nbsp; · &nbsp; <a href="/login">Command Center</a></span></div></div></footer></body></html>'''
def hero(kicker,title,desc):return f'<section class="hero"><div class="wrap"><span class="eyebrow">{kicker}</span><h1>{title}</h1><p>{desc}</p></div></section>'
def card(p,i=0):
 img=f'<img src="{e(p["image"])}" loading="lazy" decoding="async" width="480" height="267" alt="{e(p["title"])}">' if p['image'] else f'<span class="project-monogram">{e(p["title"])}</span>'
 label='Advanced backend' if p['complexity']=='advanced' else 'Mobile application' if p['complexity']=='mobile' else 'Simple website'
 return f'<article class="project-card"><a class="project-cover" data-tone="{i%5}" href="/project.html?id={e(p["id"])}" aria-label="Explore {e(p["title"])}">{img}</a><div class="project-info"><div class="project-meta"><span class="badge {p["complexity"]}">{label}</span><small>{e(p["category"])}</small></div><h3><a href="/project.html?id={e(p["id"])}">{e(p["title"])}</a></h3><p>{e(p["summary"])}</p><a class="text-link" href="/project.html?id={e(p["id"])}">Explore project ↗</a></div></article>'
services=[('Websites & e-commerce','A considered online presence, from service websites to stores and custom web applications.','/web-development.html','Web development'),('Mobile applications','Bring your idea to Android, iOS and the people who need it, with an experience built around them.','/mobile-app-development.html','Mobile apps'),('Business systems & automation','Connect the everyday parts of your business. Reduce repeated admin and create a clearer way to work.','/business-automation.html','Automation'),('Branding & graphic design','Give your business a consistent visual identity across digital experiences and marketing materials.','/graphic-design.html','Branding'),('UI & UX design','Turn complicated journeys into clear, usable screens for your website or product.','/ui-ux-design.html','Product design'),('Care & ongoing support','Keep your website maintained, updated and supported as your business changes.','/subscriptions.html','Website care')]
def svc(n=6):return '<div class="grid">'+''.join(f'<article class="service-card"><span class="service-number">0{i+1} / {e(s[3])}</span><h3>{e(s[0])}</h3><p>{e(s[1])}</p><a class="text-link" href="{s[2]}">More information ↗</a></article>' for i,s in enumerate(services[:n]))+'</div>'
art='''<div class="product-art" aria-label="Websites, business systems and applications"><div class="art-top"><span>THE ICREATE APPROACH</span><span>JM → WORLD</span></div><div class="art-title">Your idea.<br>A working digital experience.</div><div class="art-stack"><div class="art-item"><span>01 &nbsp; A website that feels like you<small>Design · Development · Launch</small></span><span>↗</span></div><div class="art-item"><span>02 &nbsp; A business that runs better<small>Systems · Automation · Management</small></span><span>↗</span></div><div class="art-item"><span>03 &nbsp; Room to keep growing<small>Mobile apps · Support · New ideas</small></span><span>↗</span></div></div><div class="art-bottom"><span class="dot"></span> JAMAICAN CREATIVITY. PRACTICAL TECHNOLOGY.</div></div>'''
home=f'''<section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">Independent ideas. Real-world solutions.</span><h1>Great ideas deserve<br><em>to be built.</em></h1><p>Websites, apps and business systems that turn your next idea into something people can actually use. Created in Jamaica, for businesses everywhere.</p><div class="actions"><a class="button" href="/contact">Let's build your idea <span>↗</span></a><a class="button secondary" href="/portfolio">Explore our portfolio</a></div><p class="subtle">From your first website to the system behind your business.</p></div>{art}</div></section><div class="trust-strip"><div class="wrap"><span>Jamaican roots · Global reach</span><span>Websites &amp; mobile apps</span><span>Custom business systems</span><span>Built around your needs</span></div></div>
<section class="section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">What we do</span><h2>Made to look good.<br>Built to work hard.</h2></div><a class="text-link" href="/services">All services ↗</a></div>{svc(3)}</div></section>
<section class="section soft"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">Selected portfolio</span><h2>Ideas we've brought to life.</h2></div><a class="text-link" href="/portfolio">View the full portfolio ↗</a></div><div class="grid" id="featured-projects">{''.join(card(p,i) for i,p in enumerate(D['projects'][:3]))}</div></div></section>
<section class="section"><div class="wrap two-col"><div><span class="eyebrow">Our own products</span><h2>Local ideas.<br>Useful possibilities.</h2><p class="intro">Alongside client work, we create products that make technology more accessible.</p></div><div><article class="timeline-item"><span>01 / GRACE CONNECT</span><h3>Faith and fellowship, connected.</h3><p>A Christian community and church platform born in Jamaica.</p><a class="text-link" href="/project.html?id=grace-connect">Meet Grace Connect ↗</a></article><article class="timeline-item"><span>02 / ICSS BOOKINGS</span><h3>A professional presence within reach.</h3><p>A website experience and booking system for service businesses working with a smaller budget.</p><a class="text-link" href="/project.html?id=icss-bookings">Explore ICSS Bookings ↗</a></article></div></div></section>
<section class="section dark"><div class="wrap two-col"><div><span class="eyebrow">The people behind the work</span><h2>Creativity started it.<br>Curiosity took it further.</h2></div><div><p>What began with animation and graphic design became a passion for building websites and software. Officially registered in July 2025, iCreate Solutions &amp; Services is here to help Jamaican businesses and clients around the world turn ideas into useful digital experiences.</p><a class="button" href="/about">Read our story ↗</a></div></div></section>
<section class="section"><div class="wrap section-heading"><div><span class="eyebrow">Your next step</span><h2>Something in mind?<br>Let's give it structure.</h2></div><a class="button" href="/contact">Start a conversation ↗</a></div></section>'''
portfolio=hero('The ICSS portfolio','A closer look at<br>what we build.','Explore websites, mobile apps and the systems behind them. Every project is labelled so you can see the kind of solution involved.')+f'''<section class="section"><div class="wrap"><div class="filters"><label>Search projects<input type="search" id="project-search" placeholder="Name, service or technology"></label><label>Category<select id="project-category"><option value="">All categories</option>{''.join(f'<option>{e(c)}</option>' for c in sorted(set(p['category'] for p in D['projects'])))}</select></label><label>System type<select id="project-complexity"><option value="">All project types</option><option value="simple">Simple website</option><option value="advanced">Advanced backend</option><option value="mobile">Mobile application</option></select></label></div><p class="subtle" id="project-count" aria-live="polite">{len(D['projects'])} projects</p><div class="grid" id="portfolio-projects">{''.join(card(p,i) for i,p in enumerate(D['projects']))}</div><noscript><p>Enable JavaScript to use the filters and read project details.</p></noscript></div></section>'''
a=D['about']
about=hero(e(a['eyebrow']),e(a['title']),'A story of creativity, curiosity and building something useful.')+f'''<section class="section"><div class="wrap two-col"><div class="story" id="about-story">{''.join('<p>'+e(p)+'</p>' for p in a['story'])}<blockquote class="quote" id="about-motto">{e(a['motto'])}</blockquote><a class="button" id="company-linkedin" href="{e(a['linkedin'])}" target="_blank" rel="noopener noreferrer">Follow ICSS on LinkedIn ↗</a></div><aside class="timeline"><div class="timeline-item"><span>2023 / THE IDEA</span><h3>A name and a creative spark.</h3><p>Animation as a hobby. Graphic design along the way. The iCreate idea begins.</p></div><div class="timeline-item"><span>THE TURNING POINT</span><h3>That first website.</h3><p>Discovering coding while working at Conduent opened a new direction.</p></div><div class="timeline-item"><span>JULY 2025 / OFFICIALLY REGISTERED</span><h3>iCreate becomes a business.</h3><p>A clear commitment to building digital solutions for real needs.</p></div><div class="timeline-item"><span>TODAY / STILL BUILDING</span><h3>Solutions with local roots.</h3><p>Client projects, Grace Connect, ICSS Bookings and the ambition to serve businesses everywhere.</p></div></aside></div></section><section class="section soft"><div class="wrap section-heading"><div><span class="eyebrow">Build with Jamaican talent</span><h2>Your next idea could start here.</h2></div><a class="button" href="/contact">Work with ICSS ↗</a></div></section>'''
form='''<form class="form" id="opportunity-form"><label>I'm interested in<select name="type" id="application-type"><option value="referral">Referral program</option></select></label><label id="job-field" hidden>Vacancy<select name="jobId" id="application-job"></select></label><label>Your name<input name="name" autocomplete="name" maxlength="150" required></label><label>Email address<input name="email" type="email" autocomplete="email" maxlength="254" required></label><label>Phone / WhatsApp<input name="phone" type="tel" autocomplete="tel" maxlength="60"></label><label>Portfolio or professional profile (optional)<input name="portfolioUrl" type="url" placeholder="https://" maxlength="2000"></label><label>Tell us a little about yourself<textarea name="message" maxlength="5000" required placeholder="Your experience, interests or the kinds of businesses you could refer."></textarea></label><label class="hp" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><label class="check"><input name="consent" type="checkbox" required><span>I agree that ICSS may use these details to review my request and contact me about it. <a href="/terms.html">Privacy &amp; terms</a></span></label><button class="button" type="submit">Submit request ↗</button><p class="form-status" role="status"></p></form>'''
work=hero('Careers & partnerships','Work with ICSS.','Help us turn ideas into powerful digital experiences. Explore open roles or apply to become a referral partner.')+f'''<section class="section"><div class="wrap two-col"><div><span class="eyebrow">Careers</span><h2>Find your next opportunity.</h2><div id="job-list"><div class="empty">There are no advertised vacancies right now. Check back for new opportunities.</div></div><div class="referral-panel" id="referral-info"><span class="eyebrow">Referral program</span><h3 id="referral-title">{e(D['referral']['title'])}</h3><p id="referral-description">{e(D['referral']['description'])}</p><p class="subtle" id="referral-terms">{e(D['referral']['terms'])}</p></div></div><div id="apply"><span class="eyebrow">Let's connect</span><h2>Introduce yourself.</h2>{form}</div></div></section>'''
contact=hero('Start a conversation','Tell us what<br>you have in mind.','A new website, a mobile app or a better way to run your business. Share the idea and we will work through the next step with you.')+'''<section class="section"><div class="wrap two-col"><div><span class="eyebrow">Contact ICSS</span><h2>Good work starts<br>with a conversation.</h2><p class="intro">Based in Jamaica. Working with businesses locally and around the world.</p><div class="timeline-item"><span>WHATSAPP</span><h3><a href="https://wa.me/18765857469">(876) 585-7469 ↗</a></h3></div><div class="timeline-item"><span>EMAIL</span><p><a href="mailto:iCreatesolutions.ja@gmail.com">iCreatesolutions.ja@gmail.com</a></p></div><div class="timeline-item"><span>PLAN YOUR PROJECT</span><p>Prefer to explore packages and estimate a project first?</p><a class="text-link" href="/project-planner.html#project-estimator">Open the project planner ↗</a></div></div><form class="form" id="contact-form"><label>Your name<input name="name" autocomplete="name" maxlength="150" required></label><label>Business name (optional)<input name="business_name" autocomplete="organization" maxlength="200"></label><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Phone / WhatsApp (optional)<input name="phone" type="tel" autocomplete="tel"></label><label>What would you like to build?<select name="service_needed"><option>Website development</option><option>Mobile application</option><option>Business system or automation</option><option>Branding or graphic design</option><option>UI / UX design</option><option>Maintenance and support</option><option>Something else</option></select></label><label>Tell us about your idea<textarea name="message" maxlength="5000" required></textarea></label><label class="hp" aria-hidden="true">Website<input name="honeypot" tabindex="-1" autocomplete="off"></label><label class="check"><input name="consent" type="checkbox" required><span>I agree to be contacted about this request. <a href="/terms.html">Privacy &amp; terms</a></span></label><button class="button" type="submit">Send inquiry ↗</button><p class="form-status" role="status"></p></form></div></section>'''
service=hero('What we do','The right solution.<br>For your next step.','From a clear first impression to the software behind your operations. Explore a service to see how ICSS can help.')+f'<section class="section"><div class="wrap">{svc()}</div></section>'+'''<section class="section soft"><div class="wrap two-col"><div><span class="eyebrow">How we work</span><h2>Clear from the start.</h2><p class="intro">We start with your goals, agree on the scope and build around the people who will use the solution.</p></div><div class="timeline"><div class="timeline-item"><span>01 / UNDERSTAND</span><h3>Your goals and your workflow.</h3><p>Tell us what you need to improve, who it serves and what is practical for your budget.</p></div><div class="timeline-item"><span>02 / CREATE</span><h3>Design, build and refine.</h3><p>Review the work as it comes together, with clear decisions about features and content.</p></div><div class="timeline-item"><span>03 / LAUNCH & SUPPORT</span><h3>Get it working in the real world.</h3><p>Launch your solution and choose ongoing care that fits your business.</p></div><div class="actions"><a class="button" href="/contact">Discuss your project ↗</a><a class="button secondary" href="/subscriptions.html">View care plans</a></div></div></div></section>'''
project=hero('Portfolio / Project','A closer look.','The idea, the solution and the technology behind the experience.')+'<section class="section"><div class="wrap" id="project-detail"><p class="empty">Loading project details…</p></div></section>'
ui=hero('Product design','Clear screens.<br>Better experiences.','UI and UX design that helps people understand what to do and move confidently through your website or application.')+'<section class="section"><div class="wrap two-col"><div><span class="eyebrow">Built around people</span><h2>Make the next step obvious.</h2><p class="intro">We work through page structure, user journeys and interface design before turning the idea into a working experience.</p><div class="actions"><a class="button" href="/contact">Discuss your interface ↗</a><a class="button secondary" href="/portfolio">Explore our work</a></div></div><div class="timeline"><div class="timeline-item"><span>01 / STRUCTURE</span><h3>Organise the information.</h3><p>Plan pages, navigation and the actions visitors need to take.</p></div><div class="timeline-item"><span>02 / INTERFACE</span><h3>Bring the experience into focus.</h3><p>Shape typography, spacing, colours, components and responsive layouts.</p></div><div class="timeline-item"><span>03 / IMPLEMENTATION</span><h3>Connect the design to the build.</h3><p>Create a consistent experience across the screens people use.</p></div></div></div></section>'
(WEB/'ui-ux-design.html').write_text(shell('ui-ux-design','UI & UX Design','User experience and interface design from iCreate Solutions & Services.',ui))
for name,title,desc,body in [('index','Websites, Apps & Business Systems','Jamaican websites, mobile apps and business systems by iCreate Solutions & Services. Transforming ideas into powerful digital experiences.',home),('services','Services','Explore web development, mobile apps, branding, UI/UX, business automation and support from ICSS.',service),('portfolio','Portfolio','Explore the iCreate portfolio: Skybeach, MyHaloManage, ICSS Bookings, Grace Connect and more.',portfolio),('about','About','The iCreate story: creativity in 2023, official registration in July 2025, and digital solutions built in Jamaica for the world.',about),('work-with-icss','Work with ICSS','Find career opportunities at iCreate Solutions & Services or apply to join our referral program.',work),('contact','Contact','Contact iCreate Solutions & Services about websites, apps, automation and your next digital project.',contact),('project','Portfolio project','Explore a project built by iCreate Solutions & Services.',project)]:
 (WEB/f'{name}.html').write_text(shell(name,title,desc,body))
